"""Write src/core/html-entities.ts from Python's html module, so that labels.ts can
unescape entities exactly like html.unescape does.

Run from web/: .venv/bin/python scripts/gen-html-entities.py
"""

import html
import html.entities
import json
import sys
from pathlib import Path

target = Path(__file__).resolve().parent.parent / "src" / "core" / "html-entities.ts"


def js(value) -> str:
    return json.dumps(value, ensure_ascii=True)


lines = [
    "// Generated by scripts/gen-html-entities.py from Python "
    f"{sys.version_info.major}.{sys.version_info.minor}'s html module. Do not edit.",
    "",
    "/** HTML5 named character references, as in html.entities.html5. */",
    "export const HTML5: Record<string, string> = {",
]
lines += [f"  {js(name)}: {js(value)}," for name, value in html.entities.html5.items()]
lines += [
    "};",
    "",
    "/** Numeric references that browsers map to other characters (html._invalid_charrefs). */",
    "export const INVALID_CHARREFS: Record<number, string> = {",
]
lines += [f"  {num}: {js(value)}," for num, value in sorted(html._invalid_charrefs.items())]
lines += [
    "};",
    "",
    "/** Code points that a numeric reference turns into nothing (html._invalid_codepoints). */",
    "export const INVALID_CODEPOINTS: ReadonlySet<number> = new Set([",
]
codes = sorted(html._invalid_codepoints)
lines += ["  " + ", ".join(str(c) for c in codes[i:i + 12]) + "," for i in range(0, len(codes), 12)]
lines += ["]);", ""]
target.write_text("\n".join(lines), encoding="utf-8")
print(f"wrote {target}")
